-- 数据部新人 · 电商库种子数据（固定种子生成，请勿手改）
BEGIN TRANSACTION;

CREATE TABLE users (
  user_id       INTEGER PRIMARY KEY,
  name          TEXT,
  phone         TEXT,
  city          TEXT,
  channel       TEXT,
  register_time TEXT
);

CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  name       TEXT,
  category   TEXT,
  price      REAL,
  cost       REAL,
  on_sale    INTEGER
);

CREATE TABLE orders (
  order_id     INTEGER PRIMARY KEY,
  user_id      INTEGER,
  order_time   TEXT,
  status       TEXT,
  order_source TEXT,
  total_amount REAL
);

CREATE TABLE order_items (
  item_id         INTEGER PRIMARY KEY,
  order_id        INTEGER,
  product_id      INTEGER,
  quantity        INTEGER,
  unit_price      REAL,
  discount_amount REAL
);

CREATE TABLE payments (
  payment_id INTEGER PRIMARY KEY,
  order_id   INTEGER,
  paid_time  TEXT,
  method     TEXT,
  amount     REAL,
  status     TEXT
);

CREATE TABLE refunds (
  refund_id   INTEGER PRIMARY KEY,
  order_id    INTEGER,
  refund_time TEXT,
  amount      REAL,
  reason      TEXT
);

CREATE TABLE shipments (
  shipment_id INTEGER PRIMARY KEY,
  order_id    INTEGER,
  ship_time   TEXT,
  arrive_time TEXT,
  status      TEXT
);

CREATE TABLE events (
  event_id   INTEGER PRIMARY KEY,
  user_id    INTEGER,
  event_time TEXT,
  event_type TEXT,
  product_id INTEGER
);

CREATE TABLE coupons (
  coupon_id   INTEGER PRIMARY KEY,
  user_id     INTEGER,
  coupon_type TEXT,
  amount      REAL,
  used        INTEGER,
  expire_time TEXT
);


